import json
passages={p['id']:p for p in json.load(open('/work/report-passages.json'))}
items=[]
def ids(*parts):
 out=set()
 for p in parts:
  if isinstance(p,int):out.add(p)
  else:out.update(range(p[0],p[1]+1))
 return [f'P{i:04}' for i in sorted(out)]
def add(title,loc,src,status,severity,note,noise=None):
 reports=''.join(sorted({passages[p]['report'] for p in src}))
 items.append(dict(item=title,loc=loc,sources=src,reports=reports,status=status,severity=severity,noise_class=noise,note=note))
