with open('/work/tmp/findings.jsonl','w') as f:
 for x in items:f.write(json.dumps(x,ensure_ascii=False)+'\n')
print('union items:',len(items));print('statuses:',__import__('collections').Counter(x['status'] for x in items));print('reports:',[(i+1,x['reports'],x['item']) for i,x in enumerate(items)])
